-- ============================================================================
-- B4/B5 ROUND-OFF, CAPSTONE COPY: cementing / advanced prompt.
--
-- min_standoff_rigid grades the smallest rigid standoff over the whole string.
-- The engine (cementing.js standoffProfile) evaluates every 30 m interval: the
-- blade ratio in that interval's bore, less that interval's sag. The cased
-- 13-3/8 inch bore is wider, so its ratio is lower, (0.29 -
-- 0.244475)/(0.315341 - 0.244475) = 0.6424096181525695, and the well is
-- vertical to 500 m, so no sag is subtracted there. The open hole minimum is
-- 0.6827896512935882 less its sag = 0.6543142173967237. The prompt said field
-- 5 is "not the blade ratio" and that the sag is subtracted, which sends a
-- learner to 0.65431 in the open hole, a fail. The engine is physically right
-- (a rigid blade stands a pipe off less in a bigger hole; a vertical pipe does
-- not sag), so the copy is corrected and nothing is regraded.
--
-- THE EDIT (prompt text only):
--   was: then 3 by bisection, then 5.
--   now: then 3 by bisection, then 5, interval by interval.
--   was: Field 5 is not the blade ratio: the sag is subtracted from it exactly as it is for a bow spring.
--   now: Field 5 is the smallest rigid standoff anywhere on the string, cased hole and open hole alike: in each interval the sag is subtracted from the blade ratio of that interval's bore exactly as it is for a bow spring, and where the well is vertical the sag is zero.
--
-- WHAT DOES NOT MOVE. `fields` (every key, label, unit, expected value and
-- tolerance), title, dataset, status and the row itself. The guard below
-- requires `fields` to equal its live value exactly, before and after. No
-- stored attempt is re-scored and no answer grades differently.
--
-- GUARDS. The prompt must hold its current text (md5 dac83d965fd37c84100c6fa4d9f1c50d, it is
-- updated) or the corrected one (md5 7e7412057740dcb01936e298c2026745, left alone). Anything
-- else raises and the transaction rolls back. Generated by
-- docs/graded-field-audit/roundoff_capstones.py from a scratch replay of main
-- plus 20261021a/b and 20261022. Runs after those. SAFE TO RE-RUN.
-- ============================================================================

do $$
declare
  v_n       integer;
  v_state   text;
  v_count   integer;
begin
  select count(*) into v_n from public.academy_capstones where app_slug = 'cementing' and tier = 'advanced' and active;
  if v_n <> 1 then raise exception 'roundoff capstone cementing/advanced refused: % active capstone rows, expected 1', v_n; end if;

  select case when md5(prompt) = 'dac83d965fd37c84100c6fa4d9f1c50d' then 'old'
              when md5(prompt) = '7e7412057740dcb01936e298c2026745' then 'new'
              else 'other' end
    into v_state
    from public.academy_capstones where app_slug = 'cementing' and tier = 'advanced' and active;
  if v_state = 'other' then raise exception 'roundoff capstone cementing/advanced refused: the prompt matches neither its current nor its corrected form'; end if;
  if (select fields from public.academy_capstones where app_slug = 'cementing' and tier = 'advanced' and active)
     is distinct from '[{"key": "min_standoff", "tol": 5e-07, "unit": "-", "label": "Minimum standoff", "expected": 0.8556417628346304}, {"key": "standoff_at_centralizer_at_min", "tol": 5e-07, "unit": "-", "label": "Standoff at the centralizer", "expected": 0.8841171967314949}, {"key": "required_spacing_m", "tol": 5e-07, "unit": "m", "label": "Required spacing", "expected": 15.99770776601963}, {"key": "buoyed_weight_n_per_m", "tol": 0.0005, "unit": "N/m", "label": "Buoyed weight", "expected": 572.3226608514}, {"key": "min_standoff_rigid", "tol": 5e-07, "unit": "-", "label": "Minimum standoff, rigid", "expected": 0.6424096181525695}, {"key": "centralizer_spring_rate_n_per_m", "tol": 0.005, "unit": "N/m", "label": "Spring rate", "expected": 999875.0156230475}]'::jsonb then
    raise exception 'roundoff capstone cementing/advanced refused: fields differ from the live fields this file was generated against';
  end if;

  if v_state = 'old' then
    update public.academy_capstones
       set prompt = 'Six centralization numbers for the Associate capstone''s string. The casing is 9-5/8 inch at 0.244475 m outside and 0.2204974 inside, weighing 69.9437033 kg per metre, on the same slant trajectory. The hole is cased to 350 m at 0.315341 m and open hole to 1400 at 0.31115. The centralizer is a BOW SPRING at 10.5 m spacing with a restoring force of 11000 N quoted at the standard 0.67. The mud is 1300 kg/m3, not the lessons'' 1440. A RIGID blade of 0.29 m is to be evaluated on the same string at the same spacing. Report: (1) the MINIMUM STANDOFF with the bow springs; (2) the STANDOFF AT THE CENTRALIZER at the interval where that minimum occurs; (3) the REQUIRED SPACING to reach the API target, in metres; (4) the BUOYED WEIGHT per metre at 1300 kg/m3, in newtons per metre; (5) the MINIMUM STANDOFF with the 0.29 m RIGID blade at the same spacing; and (6) the SPRING RATE of the 11000 N bow spring in the open hole, in newtons per metre. Do field 4 first, then field 6, then 1 and 2 from one profile, then 3 by bisection, then 5, interval by interval. Traps. The 30 percent excess of the other two capstones appears NOWHERE here: standoffProfile runs the annulus at zero excess, so a clearance of about 0.042 rather than 0.033 means the wrong bore was used. The casing is 9-5/8 inch, so its clearance, its weight and its bending stiffness all differ from the lessons''. The mud is LIGHTER, so the casing is heavier in the hole and the standoff slightly worse. Field 5 is the smallest rigid standoff anywhere on the string, cased hole and open hole alike: in each interval the sag is subtracted from the blade ratio of that interval''s bore exactly as it is for a bow spring, and where the well is vertical the sag is zero. Free checks: field 1 must be at or below field 2; field 3 must EXCEED the 10.5 m being run, because the job passes; field 6 times 0.33 times the open hole clearance must give back 11000 N; and field 1 passes the API 67 percent while field 5 does not.'
     where app_slug = 'cementing' and tier = 'advanced' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'roundoff capstone cementing/advanced refused: updated % rows', v_count; end if;
  end if;

  if (select md5(prompt) from public.academy_capstones where app_slug = 'cementing' and tier = 'advanced' and active)
     <> '7e7412057740dcb01936e298c2026745' then
    raise exception 'roundoff capstone cementing/advanced refused: the prompt does not read back as the corrected text';
  end if;
  raise notice 'roundoff capstone cementing/advanced: % of 1 prompt written', case when v_state = 'old' then 1 else 0 end;
end $$;
